package main

import "fmt"

func coinChange(coins []int, amount int) int {
	unreachable := amount + 1 // more coins than any real answer needs
	// fewest[a] is the fewest coins that add up to a.
	// fewest[0] stays 0, and every other entry starts out unreachable.
	fewest := make([]int, amount+1)
	for a := 1; a <= amount; a++ {
		fewest[a] = unreachable
		for _, coin := range coins {
			if coin <= a && fewest[a-coin]+1 < fewest[a] {
				fewest[a] = fewest[a-coin] + 1
			}
		}
	}
	if fewest[amount] == unreachable {
		return -1
	}
	return fewest[amount]
}

func main() {
	var n int
	fmt.Scan(&n)
	coins := make([]int, n)
	for i := range coins {
		fmt.Scan(&coins[i])
	}
	var amount int
	fmt.Scan(&amount)
	fmt.Println(coinChange(coins, amount))
}

