import { readFileSync } from "node:fs";

const input = readFileSync(0, "utf8");

function coinChange(coins: number[], amount: number): number {
  const unreachable = amount + 1; // more coins than any real answer needs
  // fewest[a] is the fewest coins that add up to a.
  const fewest: number[] = new Array<number>(amount + 1).fill(unreachable);
  fewest[0] = 0;
  for (let a = 1; a <= amount; a++) {
    let best = unreachable;
    for (const coin of coins) {
      if (coin <= a) {
        best = Math.min(best, (fewest[a - coin] ?? unreachable) + 1);
      }
    }
    fewest[a] = best;
  }
  const answer = fewest[amount] ?? unreachable;
  return answer === unreachable ? -1 : answer;
}

const tokens = input.trim().split(/\s+/).map(Number);
const n = tokens[0] ?? 0;
const coins = tokens.slice(1, n + 1);
const amount = tokens[n + 1] ?? 0;
console.log(coinChange(coins, amount));
